    words = text.split()
    if not words:
        return 0.0
    high_vowel_word_count = sum(1 for word in words if sum(1 for c in word.lower() if c in 'aeiou') > 4)
    return high_vowel_word_count / len(words)

def feature(text: str) -> float:
