def feature(text: str) -> float:
    "Count of words that repeat"
    words = text.split()
    word_counts = {}
    for word in words:
        word_counts[word] = word_counts.get(word, 0) + 1
    repeated_word_count = sum(1 for count in word_counts.values() if count > 1)
    return float(repeated_word_count)
